dashboard.definition:
{
    "title": "Overview",
    "description": "This dashboard provides an overview of GreyNoise features and the GreyNoise service status.",
    "inputs": {
        "input_e1ixhNs2": {
            "options": {
                "defaultValue": "*",
                "items": [
                    {
                        "label": "All",
                        "value": "*"
                    },
                    {
                        "label": "malicious",
                        "value": "malicious"
                    },
                    {
                        "label": "suspicious",
                        "value": "suspicious"
                    },
                    {
                        "label": "benign",
                        "value": "benign"
                    },
                    {
                        "label": "unknown",
                        "value": "unknown"
                    }
                ],
                "token": "tkn_classification"
            },
            "title": "Classification",
            "type": "input.dropdown"
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {}
                }
            },
            "ds.spl2": {
                "options": {
                    "queryParameters": {}
                }
            }
        },
        "visualizations": {
            "global": {
                "showProgressBar": true
            }
        }
    },
