    "dataSources": {
        "ds_3TsmUNMJ": {
            "name": "_ of indicators in GreyNoise Feed by Classification search",
            "options": {
                "query": "| inputlookup greynoise_indicators\n| stats count by classification\n| sort -count"
            },
            "type": "ds.search"
        },
        "ds_3u1vZUlY": {
            "name": "_ of Suspicious IP Addresses in GreyNoise today search",
            "options": {
                "query": "| inputlookup gn_overview_lookup where (stats_field=classification AND classification=suspicious)\n            | table stats_count",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_BHQPBvSb": {
            "name": "_ of indicators in Callback Feed by Stage search",
            "options": {
                "query": "| inputlookup greynoise_callback_indicators\n| eval stage=case(is_stage_1=\"true\", \"1\", is_stage_2=\"true\", \"2\", 1=1, \"Unconfirmed\")\n| stats count by stage"
            },
            "type": "ds.search"
        },
        "ds_I6DwZxLP": {
            "name": "Top 10 OS search",
            "options": {
                "query": "| inputlookup gn_overview_lookup where (classification=\"$tkn_classification$\" AND stats_field=\"operating_system\")\n            | stats sum(stats_count) as stats_count by stats_value\n            | sort -stats_count\n            | head 10\n            | rename stats_value as \"Operating System\", stats_count as Count\n            | table \"Operating System\", Count",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_RR3JAVfG": {
            "name": "Percentage of Business Service IPs in the deployment search",
            "options": {
                "query": "| inputlookup gn_scan_deployment_ip_lookup\n| stats count(eval(business_service_intelligence=1)) AS business_service_ips, count(eval(business_service_intelligence=1 OR business_service_intelligence=0)) AS total_ips\n| eval business_service_percent=((business_service_ips/total_ips)*100)\n| eval business_service_percent = if(business_service_percent>0, business_service_percent, 0)\n| table business_service_percent",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_SxEP9XgM": {
            "name": "5 Most Recent Malicious IPs search",
            "options": {
                "query": "| inputlookup gn_scan_deployment_ip_lookup\n| search classification=malicious\n| eval ip=_key\n| sort -last_checked\n| head 5\n| table ip, last_checked"
            },
            "type": "ds.search"
        },
        "ds_b4EdjtlR": {
            "name": "Top 10 ASN search",
            "options": {
                "query": "| inputlookup gn_overview_lookup where (classification=\"$tkn_classification$\" AND stats_field=\"asn\")\n            | stats sum(stats_count) as stats_count by stats_value\n            | sort -stats_count\n            | head 10\n            | rename stats_value as ASN, stats_count as Count\n            | table ASN, Count",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_dQAeIOfw": {
            "name": "_ of indicators in GreyNoise Feed lookup search",
            "options": {
                "query": "| inputlookup greynoise_indicators\n| fillnull value=\"greynoise\" source_workspaces \n| stats count by source_workspaces",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_i1gmTLJV": {
            "name": "Top 10 Organizations search",
            "options": {
                "query": "| inputlookup gn_overview_lookup where (classification=\"$tkn_classification$\" AND stats_field=\"organization\")\n            | stats sum(stats_count) as stats_count by stats_value\n            | sort -stats_count\n            | head 10\n            | rename stats_value as Organization, stats_count as count\n            | table Organization, count",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_iIhg5oPK": {
            "name": "_ of Business Service IPs in the deployment search",
            "options": {
                "query": "| inputlookup gn_scan_deployment_ip_lookup where (business_service_intelligence=\"1\")\n| stats count",
